23	)
24	
25	type tblErrorType string
26	
27	const (
28		tblErrInvalid         tblErrorType = "invalid"
29		tblErrTypeNotExist    tblErrorType = "do not exist"
30		tblErrTypeInConflict  tblErrorType = "are in conflict"
31		tblErrTypeSchConflict tblErrorType = "have schema conflicts"
32		tblErrTypeConstViols  tblErrorType = "have constraint violations"
33		tblErrStagedChanges   tblErrorType = "have changes saved in the index. Use --cached or commit."
34		tblErrUnstagedChanges tblErrorType = "have unstaged changes."
35	)
36	
37	type TblError struct {
38		tables     []doltdb.TableName
39		tblErrType tblErrorType
40	}
41	
42	func NewTblNotExistError(tbls []doltdb.TableName) TblError {
43		return TblError{tbls, tblErrTypeNotExist}
44	}
45	
46	func NewTblStagedError(tbls []doltdb.TableName) TblError {
47		return TblError{tbls, tblErrStagedChanges}
48	}
49	
50	func NewTblUnstagedError(tbls []doltdb.TableName) TblError {
51		return TblError{tbls, tblErrUnstagedChanges}
52	}
53	
54	func NewTblInConflictError(tbls []doltdb.TableName) TblError {
55		return TblError{tables: tbls, tblErrType: tblErrTypeInConflict}
56	}
57	
58	func NewTblSchemaConflictError(tbls []doltdb.TableName) TblError {
59		return TblError{tables: tbls, tblErrType: tblErrTypeSchConflict}
60	}
61	
62	func NewTblHasConstraintViolations(tbls []doltdb.TableName) TblError {
63		return TblError{tbls, tblErrTypeConstViols}
64	}
65	
66	func (te TblError) Error() string {
67		sb := strings.Builder{}
68		sb.WriteString("error: the table(s) ")
69		for i, tbl := range te.tables {
70			if i > 0 {
71				sb.WriteString(", ")
72			}
73			sb.WriteString(tbl.String())
74		}
75		sb.WriteString(" ")
76		sb.WriteString(string(te.tblErrType))
77		return sb.String()
78	}
79	
80	func getTblErrType(err error) tblErrorType {
81		te, ok := err.(TblError)
82	
83		if ok {
84			return te.tblErrType
85		}
86	
87		return tblErrInvalid
88	}
89	
90	func IsTblError(err error) bool {
91		return getTblErrType(err) != tblErrInvalid
92	}
93	
94	func IsTblNotExist(err error) bool {
95		return getTblErrType(err) == tblErrTypeNotExist
96	}
97	
98	func IsTblInConflict(err error) bool {
99		return getTblErrType(err) == tblErrTypeInConflict
100	}
101	
102	func IsTblViolatesConstraints(err error) bool {
103		return getTblErrType(err) == tblErrTypeConstViols
104	}
105	
106	func GetTablesForError(err error) []doltdb.TableName {
107		te, ok := err.(TblError)
108	
109		if !ok {
110			panic("Must validate with IsTblError or more specific methods before calling GetTablesForError")
111		}
112	
113		return te.tables
114	}
115	
116	type ErrCheckoutWouldOverwrite struct {
117		tables []string
118	}
119	
120	func (cwo ErrCheckoutWouldOverwrite) Error() string {
121		var buffer bytes.Buffer
122		buffer.WriteString("Your local changes to the following tables would be overwritten by checkout:\n")
123		for _, tbl := range cwo.tables {
124			buffer.WriteString("\t" + tbl + "\n")
125		}
126	
127		buffer.WriteString("Please commit your changes or stash them before you switch branches.\n")
128		buffer.WriteString("Aborting")
129		return buffer.String()
130	}
131	
132	func IsCheckoutWouldOverwrite(err error) bool {
133		_, ok := err.(ErrCheckoutWouldOverwrite)
134		return ok
135	}
136	
137	func CheckoutWouldOverwriteTables(err error) []string {
138		cwo, ok := err.(ErrCheckoutWouldOverwrite)
139	
140		if !ok {
141			panic("Must validate with IsCheckoutWouldOverwrite before calling CheckoutWouldOverwriteTables")
142		}
143	
144		return cwo.tables
145	}
146	
147	type NothingStaged struct {
148		NotStagedTbls []diff.TableDelta
149	}
150	
151	func (ns NothingStaged) Error() string {
152		return "no changes added to commit"
153	}
154	
155	func IsNothingStaged(err error) bool {
156		_, ok := err.(NothingStaged)
157		return ok
158	}
159	
160	func NothingStagedTblDiffs(err error) []diff.TableDelta {
161		ns, ok := err.(NothingStaged)
162	
163		if !ok {
164			panic("Must validate with IsCheckoutWouldOverwrite before calling CheckoutWouldOverwriteTables")
165		}
166	
167		return ns.NotStagedTbls
168	}
