32	// MoveTablesFromHeadToWorking replaces the tables named from the given head to the given working root, overwriting any
33	// working changes, and returns the new resulting roots
34	func MoveTablesFromHeadToWorking(ctx context.Context, roots doltdb.Roots, tbls []doltdb.TableName) (doltdb.Roots, error) {
35		var unknownTbls []doltdb.TableName
36		for _, tblName := range tbls {
37			tbl, ok, err := roots.Staged.GetTable(ctx, tblName)
38			if err != nil {
39				return doltdb.Roots{}, err
40			}
41			fkc, err := roots.Staged.GetForeignKeyCollection(ctx)
42			if err != nil {
43				return doltdb.Roots{}, err
44			}
45	
46			if !ok {
47				tbl, ok, err = roots.Head.GetTable(ctx, tblName)
48				if err != nil {
49					return doltdb.Roots{}, err
50				}
51	
52				fkc, err = roots.Head.GetForeignKeyCollection(ctx)
53				if err != nil {
54					return doltdb.Roots{}, err
55				}
56	
57				if !ok {
58					unknownTbls = append(unknownTbls, tblName)
59					continue
60				}
61			}
62	
63			roots.Working, err = roots.Working.PutTable(ctx, tblName, tbl)
64			if err != nil {
65				return doltdb.Roots{}, err
66			}
67	
68			roots.Working, err = roots.Working.PutForeignKeyCollection(ctx, fkc)
69			if err != nil {
70				return doltdb.Roots{}, err
71			}
72		}
73	
74		if len(unknownTbls) > 0 {
75			// Return table not exist error before RemoveTables, which fails silently if the table is not on the root.
76			err := validateTablesExist(ctx, roots.Working, unknownTbls)
77			if err != nil {
78				return doltdb.Roots{}, err
79			}
80	
81			roots.Working, err = roots.Working.RemoveTables(ctx, false, false, unknownTbls...)
82	
83			if err != nil {
84				return doltdb.Roots{}, err
85			}
86		}
87	
88		return roots, nil
89	}
