91	// FindTableInRoots resolves a table by looking in all three roots (working,
92	// staged, head) in that order.
93	func FindTableInRoots(ctx *sql.Context, roots doltdb.Roots, name string) (doltdb.TableName, *doltdb.Table, bool, error) {
94		tbl, root, tblExists, err := resolve.Table(ctx, roots.Working, name)
95		if err != nil {
96			return doltdb.TableName{}, nil, false, err
97		}
98		if tblExists {
99			return tbl, root, true, nil
100		}
101	
102		tbl, root, tblExists, err = resolve.Table(ctx, roots.Staged, name)
103		if err != nil {
104			return doltdb.TableName{}, nil, false, err
105		}
106		if tblExists {
107			return tbl, root, true, nil
108		}
109	
110		tbl, root, tblExists, err = resolve.Table(ctx, roots.Head, name)
111		if err != nil {
112			return doltdb.TableName{}, nil, false, err
113		}
114		if tblExists {
115			return tbl, root, true, nil
116		}
117	
118		return doltdb.TableName{}, nil, false, nil
119	}
