121	// RootsForBranch returns the roots needed for a branch checkout. |roots.Head| should be the pre-checkout head. The
122	// returned roots struct has |Head| set to |branchRoot|.
123	func RootsForBranch(ctx context.Context, roots doltdb.Roots, branchRoot doltdb.RootValue, force bool) (doltdb.Roots, error) {
124		conflicts := doltdb.NewTableNameSet(nil)
125		if roots.Head == nil {
126			roots.Working = branchRoot
127			roots.Staged = branchRoot
128			roots.Head = branchRoot
129			return roots, nil
130		}
131	
132		wrkTblHashes, err := moveModifiedTables(ctx, roots.Head, branchRoot, roots.Working, conflicts, force)
133		if err != nil {
134			return doltdb.Roots{}, err
135		}
136	
137		stgTblHashes, err := moveModifiedTables(ctx, roots.Head, branchRoot, roots.Staged, conflicts, force)
138		if err != nil {
139			return doltdb.Roots{}, err
140		}
141	
142		if conflicts.Size() > 0 {
143			return doltdb.Roots{}, ErrCheckoutWouldOverwrite{conflicts.AsStringSlice()}
144		}
145	
146		workingForeignKeys, err := moveForeignKeys(ctx, roots.Head, branchRoot, roots.Working, force)
147		if err != nil {
148			return doltdb.Roots{}, err
149		}
150	
151		stagedForeignKeys, err := moveForeignKeys(ctx, roots.Head, branchRoot, roots.Staged, force)
152		if err != nil {
153			return doltdb.Roots{}, err
154		}
155	
156		roots.Working, err = writeTableHashes(ctx, branchRoot, wrkTblHashes)
157		if err != nil {
158			return doltdb.Roots{}, err
159		}
160	
161		roots.Staged, err = writeTableHashes(ctx, branchRoot, stgTblHashes)
162		if err != nil {
163			return doltdb.Roots{}, err
164		}
165	
166		roots.Working, err = roots.Working.PutForeignKeyCollection(ctx, workingForeignKeys)
167		if err != nil {
168			return doltdb.Roots{}, err
169		}
170	
171		roots.Staged, err = roots.Staged.PutForeignKeyCollection(ctx, stagedForeignKeys)
172		if err != nil {
173			return doltdb.Roots{}, err
174		}
175	
176		roots.Head = branchRoot
177		return roots, nil
178	}
