180	// CleanOldWorkingSet resets the source branch's working set to the branch head, leaving the source branch unchanged
181	func CleanOldWorkingSet(
182		ctx *sql.Context,
183		dbData env.DbData[*sql.Context],
184		doltDb *doltdb.DoltDB,
185		username, email string,
186		initialRoots doltdb.Roots,
187		initialHeadRef ref.DoltRef,
188		initialWs *doltdb.WorkingSet,
