190		// reset the source branch's working set to the branch head, leaving the source branch unchanged
191		err := ResetHard(ctx, dbData, doltDb, username, email, "", initialRoots, initialHeadRef, initialWs)
192		if err != nil {
193			return err
194		}
195	
196		// Annoyingly, after the ResetHard above we need to get all the roots again, because the working set has changed
197		cm, err := doltDb.ResolveCommitRef(ctx, initialHeadRef)
198		if err != nil {
199			return err
200		}
201	
202		headRoot, err := cm.ResolveRootValue(ctx)
203		if err != nil {
204			return err
205		}
206	
207		workingSet, err := doltDb.ResolveWorkingSet(ctx, initialWs.Ref())
