218		// we also have to do a clean, because we the ResetHard won't touch any new tables (tables only in the working set)
219		newRoots, err := CleanUntracked(ctx, resetRoots, []string{}, false, true, false)
220		if err != nil {
221			return err
222		}
223	
224		h, err := workingSet.HashOf()
225		if err != nil {
226			return err
227		}
228	
229		err = doltDb.UpdateWorkingSet(
230			ctx,
231			initialWs.Ref(),
232			initialWs.WithWorkingRoot(newRoots.Working).WithStagedRoot(newRoots.Staged).ClearMerge().ClearRebase(),
233			h,
234	
235			&datas.WorkingSetMeta{
236				Name:        username,
237				Email:       email,
238				Timestamp:   uint64(time.Now().Unix()),
239				Description: "reset hard",
240			},
241			nil,
242		)
243		if err != nil {
244			return err
245		}
246		return nil
247	}
