222	func generateSuccessMessage(newBranch, upstream string) string {
223		result := fmt.Sprintf("Switched to branch '%s'", newBranch)
224		if upstream != "" {
225			result += fmt.Sprintf("\nbranch '%s' set up to track '%s'.", newBranch, upstream)
226		}
227		return result
228	}
