61	func convertTupleToIgnoreBoolean(ctx context.Context, valueDesc *val.TupleDesc, valueTuple val.Tuple) (bool, error) {
62		if !valueDesc.Equals(val.NewTupleDescriptor(val.Type{Enc: val.Int8Enc, Nullable: false})) {
63			return false, fmt.Errorf("dolt_ignore had unexpected value type, this should never happen")
64		}
65		ignore, ok := valueDesc.GetBool(0, valueTuple)
66		if !ok {
67			return false, fmt.Errorf("could not read boolean")
68		}
69		return ignore, nil
