72	func getIgnoreTablePatternKey(ctx context.Context, keyDesc *val.TupleDesc, keyTuple val.Tuple) (string, error) {
73		if !keyDesc.Equals(val.NewTupleDescriptor(val.Type{Enc: val.StringEnc, Nullable: false})) {
74			return "", fmt.Errorf("dolt_ignore had unexpected key type, this should never happen")
75		}
76		key, ok := keyDesc.GetString(0, keyTuple)
77		if !ok {
78			return "", fmt.Errorf("could not read pattern")
