83	func GetIgnoredTablePatterns(ctx context.Context, roots Roots, schemas []string) (map[string]IgnorePatterns, error) {
84		ignorePatternsForSchemas := make(map[string]IgnorePatterns)
85		workingSet := roots.Working
86	
87		for _, schemaName := range schemas {
88			var ignorePatterns []IgnorePattern
89	
90			tname := TableName{Name: IgnoreTableName, Schema: schemaName}
91			table, found, err := workingSet.GetTable(ctx, tname)
92			if err != nil {
93				return nil, err
94			}
95			if !found {
96				// dolt_ignore doesn't exist, so don't filter any tables.
97				continue
98			}
99			index, err := table.GetRowData(ctx)
100			if err != nil {
101				return nil, err
102			}
103			ignoreTableSchema, err := table.GetSchema(ctx)
104			if err != nil {
105				return nil, err
106			}
107			m := durable.MapFromIndex(index)
108			keyDesc, valueDesc := ignoreTableSchema.GetMapDescriptors(m.NodeStore())
109	
110			ignoreTableMap, err := m.IterAll(ctx)
111			if err != nil {
112				return nil, err
113			}
114			for {
115				keyTuple, valueTuple, err := ignoreTableMap.Next(ctx)
116				if err == io.EOF {
117					break
118				}
119				if err != nil {
120					return nil, err
121				}
122	
123				pattern, err := GetIgnoreTablePatternKey(ctx, keyDesc, keyTuple)
124				if err != nil {
125					return nil, err
126				}
127	
128				ignore, err := ConvertTupleToIgnoreBoolean(ctx, valueDesc, valueTuple)
129				if err != nil {
130					return nil, err
131				}
132				ignorePatterns = append(ignorePatterns, NewIgnorePattern(pattern, ignore))
133			}
134	
135			ignorePatternsForSchemas[schemaName] = ignorePatterns
136		}
137	
138		return ignorePatternsForSchemas, nil
139	}
